recipes.code:
{
  "inputs": [
    {
      "id": "borealhost-api-key",
      "type": "promptString",
      "description": "BorealHost API key (format: bh_<48 hex chars>). Optional — you can also call register() or set_api_key() at runtime.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "borealhost-mcp@0.2.0"
      ],
      "env": {
        "BOREALHOST_API_KEY": "${input:borealhost-api-key}"
      }
    }
  }
}
